--[[
    Visions hook menu (UI only)
    A dark, flat menu in the style of the screenshot: a search box and tabs across the top (the selected tab underlined in red),
    sub tabs as pills (Legit / Rage), two columns of collapsible sections, square check boxes with a red tick, sliders as a box with
    the value in the middle and a short white fill line, and dropdowns as a box with the picked value.

    Tabs: Aimbot, Visuals, Misc, Player List, Skins, Settings.
    Nothing here does anything to the game: every control only calls its Callback (print by default) so it can be wired up later.

    Right Shift opens and closes the menu. Drag it by the top bar.
    Every run starts with the VISIONS HOOK intro (see "intro" below).
]]

local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")
local TweenService = game:GetService("TweenService")

local LocalPlayer = Players.LocalPlayer

-------------------------------------------------------------------------------- theme

local Theme = {
    Window = Color3.fromRGB(24, 24, 24),
    WindowBorder = Color3.fromRGB(44, 44, 44),
    Body = Color3.fromRGB(28, 28, 28),
    Header = Color3.fromRGB(38, 38, 38),
    Element = Color3.fromRGB(40, 40, 40),
    ElementHover = Color3.fromRGB(48, 48, 48),
    Pill = Color3.fromRGB(42, 42, 42),
    Line = Color3.fromRGB(46, 46, 46),
    Text = Color3.fromRGB(235, 235, 235),
    TextDim = Color3.fromRGB(140, 140, 140),
    Accent = Color3.fromRGB(214, 74, 74),
    Font = Enum.Font.Gotham,
    FontBold = Enum.Font.GothamMedium,
    TextSize = 13,
}

-------------------------------------------------------------------------------- helpers

local function new(class, props, parent)
    local object = Instance.new(class)

    for key, value in pairs(props or {}) do
        object[key] = value
    end

    if parent then
        object.Parent = parent
    end

    return object
end

local function corner(parent, radius)
    return new("UICorner", { CornerRadius = UDim.new(0, radius or 4) }, parent)
end

local function tween(object, props, time)
    local t = TweenService:Create(object, TweenInfo.new(time or 0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), props)
    t:Play()
    return t
end

local function guiParent()
    local ok, hui = pcall(function()
        return gethui and gethui()
    end)

    if ok and hui then
        return hui
    end

    local okCore, core = pcall(function()
        return game:GetService("CoreGui")
    end)

    if okCore and core then
        return core
    end

    return LocalPlayer:WaitForChild("PlayerGui")
end

local function round(value, decimals)
    local factor = 10 ^ (decimals or 0)
    return math.floor(value * factor + 0.5) / factor
end

local function formatNumber(value, decimals)
    if (decimals or 0) <= 0 then
        return tostring(math.floor(value + 0.5))
    end

    local text = string.format("%." .. decimals .. "f", value)
    return (text:gsub("(%..-)0+$", "%1"):gsub("%.$", ""))
end

-------------------------------------------------------------------------------- the razor in the top right corner

-- The picture is kept in here as base64 (a PNG, 200 x 184, transparent background), written to the executor's workspace once and shown
-- through getcustomasset. Without file functions or getcustomasset the menu simply has no picture.
local RAZOR_PNG = ""

local function decodeBase64(data)
    local ok, decoded = pcall(function()
        if crypt and crypt.base64decode then return crypt.base64decode(data) end
        if crypt and crypt.base64 and crypt.base64.decode then return crypt.base64.decode(data) end
        if base64_decode then return base64_decode(data) end
        if base64 and base64.decode then return base64.decode(data) end
        return nil
    end)

    if ok and type(decoded) == "string" then
        return decoded
    end

    -- plain Lua, for executors that have none of the above
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local lookup = {}
    for i = 1, #alphabet do
        lookup[alphabet:sub(i, i)] = i - 1
    end

    data = data:gsub("[^%w%+/=]", "")
    local out = {}

    for i = 1, #data, 4 do
        local a, b, c, d = lookup[data:sub(i, i)], lookup[data:sub(i + 1, i + 1)], lookup[data:sub(i + 2, i + 2)], lookup[data:sub(i + 3, i + 3)]
        local n = (a or 0) * 262144 + (b or 0) * 4096 + (c or 0) * 64 + (d or 0)
        out[#out + 1] = string.char(math.floor(n / 65536) % 256)
        if c then out[#out + 1] = string.char(math.floor(n / 256) % 256) end
        if d then out[#out + 1] = string.char(n % 256) end
    end

    return table.concat(out)
end

local function razorAsset()
    local ok, asset = pcall(function()
        local path = "visions_razor.png"

        if not (isfile and isfile(path)) then
            writefile(path, decodeBase64(RAZOR_PNG))
        end

        return getcustomasset(path)
    end)

    return ok and asset or nil
end

-------------------------------------------------------------------------------- intro

-- Plays once every time the script is run, before the menu shows: the VISIONS HOOK logo animation (4.2 s, 84 frames at 20 fps), its black
-- background taken out so the game shows through it. The frames are kept in here as 21 PNG sheets (4 frames of 640 x 240 stacked, 640 x 960: under the 1024 a texture may be, base64),
-- written to the workspace once and flipped through with ImageRectOffset. The video it came from has no sound: put an audio file at
-- workspace/visions_intro.mp3 (or .ogg) and it plays with it. getgenv().VISIONS_NO_INTRO = true skips it.
local INTRO_SHEETS = {
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
}
local INTRO = { FrameWidth = 640, FrameHeight = 240, Columns = 1, PerSheet = 4, Frames = 84, Fps = 20, Version = 2 }

local function playIntro()
    if getgenv and getgenv().VISIONS_NO_INTRO then
        return
    end

    local assets = {}

    local ok = pcall(function()
        for index, data in ipairs(INTRO_SHEETS) do
            local path = string.format("visions_intro_v%d_%d.png", INTRO.Version, index)

            if not (isfile and isfile(path)) then
                writefile(path, decodeBase64(data))
            end

            assets[index] = getcustomasset(path)
        end
    end)

    if not ok or #assets ~= #INTRO_SHEETS then
        return
    end

    pcall(function()
        game:GetService("ContentProvider"):PreloadAsync(assets)
    end)

    local gui = new("ScreenGui", {
        Name = "visions_intro",
        ResetOnSpawn = false,
        IgnoreGuiInset = true,
        DisplayOrder = 1000,
    })
    gui.Parent = guiParent()

    -- 60% of the screen's width, in the middle; nothing behind it (BackgroundTransparency 1), so only the logo itself is drawn
    local image = new("ImageLabel", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(0.5, 0.45),
        Size = UDim2.fromScale(0.6, 0.6),
        BackgroundTransparency = 1,
        Image = assets[1],
        ImageRectSize = Vector2.new(INTRO.FrameWidth, INTRO.FrameHeight),
        ImageRectOffset = Vector2.zero,
        ScaleType = Enum.ScaleType.Fit,
    }, gui)
    new("UIAspectRatioConstraint", { AspectRatio = INTRO.FrameWidth / INTRO.FrameHeight }, image)

    local sound

    pcall(function()
        for _, path in ipairs({ "visions_intro.mp3", "visions_intro.ogg" }) do
            if isfile and isfile(path) then
                sound = new("Sound", { SoundId = getcustomasset(path), Volume = 1 }, game:GetService("SoundService"))
                sound:Play()
                break
            end
        end
    end)

    local function show(frame)
        local sheet = math.floor(frame / INTRO.PerSheet) + 1
        local cell = frame % INTRO.PerSheet
        image.Image = assets[sheet]
        image.ImageRectOffset = Vector2.new((cell % INTRO.Columns) * INTRO.FrameWidth, math.floor(cell / INTRO.Columns) * INTRO.FrameHeight)
    end

    -- frames follow the clock, not the frame rate, so a slow client skips frames instead of playing it slower
    local started = os.clock()

    while true do
        local frame = math.floor((os.clock() - started) * INTRO.Fps)

        if frame >= INTRO.Frames then
            break
        end

        show(frame)
        task.wait()
    end

    -- the last frame is held a moment, then fades out
    task.wait(0.4)
    tween(image, { ImageTransparency = 1 }, 0.5)
    task.wait(0.5)

    if sound then
        sound:Destroy()
    end

    gui:Destroy()
end

-------------------------------------------------------------------------------- library

local Library = { Flags = {}, Connections = {}, Elements = {} }

local function track(connection)
    table.insert(Library.Connections, connection)
    return connection
end

function Library:CreateWindow(config)
    config = config or {}

    local gui = new("ScreenGui", {
        Name = "visions_menu",
        ResetOnSpawn = false,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
        IgnoreGuiInset = true,
    })
    gui.Parent = guiParent()

    -- (for testing: getgenv().MENU_PREVIEW_HIDDEN = true builds it without showing it)
    if getgenv and getgenv().MENU_PREVIEW_HIDDEN then
        gui.Enabled = false
    end

    Library.Gui = gui

    -- The window is built inside a see-through, screen-sized CanvasGroup so all of it (the razor hanging off the corner included) can fade in as
    -- one picture after the intro (Window:FadeIn). Until then it is fully transparent; afterwards it is moved back out and the group removed.
    local fadeGroup = new("CanvasGroup", {
        Name = "Fade",
        BackgroundTransparency = 1,
        GroupTransparency = 1,
        Size = UDim2.fromScale(1, 1),
    }, gui)

    local window = new("Frame", {
        Name = "Window",
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundColor3 = Theme.Window,
        BorderSizePixel = 0,
        Position = UDim2.fromScale(0.5, 0.5),
        Size = config.Size or UDim2.fromOffset(650, 720),
    }, fadeGroup)
    corner(window, 6)
    new("UIStroke", { Color = Theme.WindowBorder, Thickness = 1 }, window)

    -- the razor and its red cut, hanging off the top right corner (outside the window, so it covers none of the tabs)
    local razor = razorAsset()

    if razor then
        new("ImageLabel", {
            Name = "Razor",
            AnchorPoint = Vector2.new(1, 0),
            BackgroundTransparency = 1,
            Image = razor,
            Position = UDim2.new(1, 70, 0, -62),
            Size = UDim2.fromOffset(150, 138),
            ZIndex = 10,
        }, window)
    end

    ------------------------------------------------------------------ top bar: search + tabs

    local top = new("Frame", {
        Name = "Top",
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 58),
    }, window)

    local search = new("TextBox", {
        Name = "Search",
        BackgroundColor3 = Theme.Element,
        BorderSizePixel = 0,
        ClearTextOnFocus = false,
        Font = Theme.Font,
        PlaceholderColor3 = Theme.TextDim,
        PlaceholderText = "Search...",
        Position = UDim2.fromOffset(20, 18),
        Size = UDim2.fromOffset(220, 24),
        Text = "",
        TextColor3 = Theme.Text,
        TextSize = Theme.TextSize,
        TextXAlignment = Enum.TextXAlignment.Left,
    }, top)
    corner(search, 4)
    new("UIPadding", { PaddingLeft = UDim.new(0, 8) }, search)

    local tabBar = new("Frame", {
        Name = "Tabs",
        BackgroundTransparency = 1,
        Position = UDim2.fromOffset(256, 10),
        Size = UDim2.new(1, -266, 0, 40),
    }, top)
    new("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,
        SortOrder = Enum.SortOrder.LayoutOrder,
    }, tabBar)

    new("Frame", {
        Name = "Divider",
        BackgroundColor3 = Theme.Line,
        BorderSizePixel = 0,
        Position = UDim2.new(0, 0, 0, 58),
        Size = UDim2.new(1, 0, 0, 1),
    }, window)

    local pages = new("Frame", {
        Name = "Pages",
        BackgroundTransparency = 1,
        Position = UDim2.fromOffset(20, 70),
        Size = UDim2.new(1, -40, 1, -90),
    }, window)

    ------------------------------------------------------------------ dragging by the top bar

    do
        local dragging, dragStart, startPos = false, nil, nil

        track(top.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 then
                dragging = true
                dragStart = input.Position
                startPos = window.Position
            end
        end))

        track(UserInputService.InputChanged:Connect(function(input)
            if dragging and input.UserInputType == Enum.UserInputType.MouseMovement then
                local delta = input.Position - dragStart
                window.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
            end
        end))

        track(UserInputService.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 then
                dragging = false
            end
        end))
    end

    ------------------------------------------------------------------ open / close

    local toggleKey = config.Keybind or Enum.KeyCode.RightShift

    track(UserInputService.InputBegan:Connect(function(input, processed)
        if processed then
            return
        end

        if input.KeyCode == toggleKey then
            window.Visible = not window.Visible
        end
    end))

    local Window = { Tabs = {}, Gui = gui, Frame = window }
    local tabCount = 0
    local currentTab = nil

    function Window:SetKeybind(key)
        toggleKey = key
    end

    -- Fades the whole menu in (0.6 s by default), then takes it out of the fade group so it is drawn normally again.
    function Window:FadeIn(time)
        if not fadeGroup.Parent then
            return
        end

        time = time or 0.6
        tween(fadeGroup, { GroupTransparency = 0 }, time)
        task.delay(time + 0.05, function()
            if fadeGroup.Parent and window.Parent == fadeGroup then
                window.Parent = gui
            end

            fadeGroup:Destroy()
        end)
    end

    ------------------------------------------------------------------ search: hides the rows of the open page whose name does not match

    track(search:GetPropertyChangedSignal("Text"):Connect(function()
        local query = string.lower(search.Text)

        for _, element in ipairs(Library.Elements) do
            local match = query == "" or string.find(string.lower(element.Name), query, 1, true) ~= nil
            element.Row.Visible = match
        end
    end))

    ------------------------------------------------------------------ tabs

    function Window:AddTab(name)
        tabCount += 1

        local button = new("TextButton", {
            Name = name,
            AutoButtonColor = false,
            BackgroundTransparency = 1,
            Font = Theme.Font,
            LayoutOrder = tabCount,
            Size = UDim2.new(0, 64, 1, 0),
            Text = name,
            TextColor3 = Theme.TextDim,
            TextSize = Theme.TextSize,
        }, tabBar)

        -- tabs share the bar evenly, however many there are
        local function resize()
            local count = #tabBar:GetChildren() - 1
            for _, child in ipairs(tabBar:GetChildren()) do
                if child:IsA("TextButton") then
                    child.Size = UDim2.new(1 / math.max(count, 1), 0, 1, 0)
                end
            end
        end
        resize()

        local underline = new("Frame", {
            Name = "Underline",
            AnchorPoint = Vector2.new(0.5, 1),
            BackgroundColor3 = Theme.Accent,
            BorderSizePixel = 0,
            Position = UDim2.new(0.5, 0, 1, 0),
            Size = UDim2.new(0, 0, 0, 2),
        }, button)

        local page = new("Frame", {
            Name = name,
            BackgroundTransparency = 1,
            Size = UDim2.fromScale(1, 1),
            Visible = false,
        }, pages)

        -- sub tab pills (Legit / Rage); a tab without any shows its one page right under the bar
        local pillBar = new("Frame", {
            Name = "SubTabs",
            BackgroundTransparency = 1,
            Size = UDim2.new(1, 0, 0, 26),
            Visible = false,
        }, page)
        new("UIListLayout", {
            FillDirection = Enum.FillDirection.Horizontal,
            Padding = UDim.new(0, 10),
            SortOrder = Enum.SortOrder.LayoutOrder,
        }, pillBar)

        local body = new("Frame", {
            Name = "Body",
            BackgroundColor3 = Theme.Body,
            BorderSizePixel = 0,
            Position = UDim2.fromOffset(0, 0),
            Size = UDim2.fromScale(1, 1),
        }, page)
        corner(body, 4)

        local Tab = { Name = name, Button = button, Page = page, SubTabs = {}, Body = body }
        local subCount = 0
        local currentSub = nil

        local function select()
            if currentTab == Tab then
                return
            end

            if currentTab then
                currentTab.Page.Visible = false
                tween(currentTab.Button, { TextColor3 = Theme.TextDim })
                tween(currentTab.Button.Underline, { Size = UDim2.new(0, 0, 0, 2) })
            end

            currentTab = Tab
            page.Visible = true
            tween(button, { TextColor3 = Theme.Text })
            tween(underline, { Size = UDim2.new(0.8, 0, 0, 2) })
        end

        track(button.MouseButton1Click:Connect(select))

        if not currentTab then
            select()
        end

        -- a page: two columns of sections
        local function makeColumns(parent)
            local columns = {}

            for index, side in ipairs({ "Left", "Right" }) do
                local column = new("ScrollingFrame", {
                    Name = side,
                    AutomaticCanvasSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    CanvasSize = UDim2.new(),
                    Position = UDim2.new((index - 1) * 0.5, index == 1 and 0 or 5, 0, 0),
                    ScrollBarImageColor3 = Theme.Line,
                    ScrollBarThickness = 2,
                    Size = UDim2.new(0.5, -5, 1, 0),
                }, parent)
                new("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder }, column)
                new("UIPadding", { PaddingTop = UDim.new(0, 0), PaddingRight = UDim.new(0, 2) }, column)
                columns[side] = column
            end

            return columns
        end

        local function makeSectionApi(columns)
            local Api = {}
            local sectionCount = 0

            function Api:AddSection(sectionName, side)
                sectionCount += 1

                local column = columns[side == "Right" and "Right" or "Left"]

                local holder = new("Frame", {
                    Name = sectionName,
                    AutomaticSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 1,
                    LayoutOrder = sectionCount,
                    Size = UDim2.new(1, 0, 0, 0),
                }, column)
                new("UIListLayout", { Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder }, holder)

                local header = new("TextButton", {
                    Name = "Header",
                    AutoButtonColor = false,
                    BackgroundColor3 = Theme.Header,
                    BorderSizePixel = 0,
                    LayoutOrder = 0,
                    Size = UDim2.new(1, 0, 0, 20),
                    Text = "",
                }, holder)
                corner(header, 3)

                local arrow = new("TextLabel", {
                    BackgroundTransparency = 1,
                    Font = Theme.FontBold,
                    Position = UDim2.fromOffset(8, 0),
                    Size = UDim2.new(0, 12, 1, 0),
                    Text = "▼",
                    TextColor3 = Theme.Text,
                    TextSize = 11,
                }, header)

                new("TextLabel", {
                    BackgroundTransparency = 1,
                    Font = Theme.Font,
                    Position = UDim2.fromOffset(34, 0),
                    Size = UDim2.new(1, -40, 1, 0),
                    Text = sectionName,
                    TextColor3 = Theme.Text,
                    TextSize = Theme.TextSize,
                    TextXAlignment = Enum.TextXAlignment.Left,
                }, header)

                local content = new("Frame", {
                    Name = "Content",
                    AutomaticSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 1,
                    LayoutOrder = 1,
                    Size = UDim2.new(1, 0, 0, 0),
                }, holder)
                new("UIListLayout", { Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder }, content)
                new("UIPadding", { PaddingLeft = UDim.new(0, 14), PaddingRight = UDim.new(0, 6), PaddingBottom = UDim.new(0, 6) }, content)

                local open = true

                track(header.MouseButton1Click:Connect(function()
                    open = not open
                    content.Visible = open
                    arrow.Text = open and "▼" or "▶"
                end))

                local Section = {}
                local rowCount = 0

                local function row(height, rowName)
                    rowCount += 1

                    local frame = new("Frame", {
                        Name = rowName or "Row",
                        BackgroundTransparency = 1,
                        LayoutOrder = rowCount,
                        Size = UDim2.new(1, 0, 0, height),
                    }, content)

                    table.insert(Library.Elements, { Name = rowName or "", Row = frame })

                    return frame
                end

                local function label(parent, text, width)
                    return new("TextLabel", {
                        BackgroundTransparency = 1,
                        Font = Theme.Font,
                        Size = UDim2.new(width or 0.6, 0, 0, 20),
                        Text = text,
                        TextColor3 = Theme.Text,
                        TextSize = Theme.TextSize,
                        TextXAlignment = Enum.TextXAlignment.Left,
                    }, parent)
                end

                -------------------------------------------------- toggle: a square box, a red tick when on

                function Section:AddToggle(opts)
                    opts = opts or {}
                    local frame = row(22, opts.Name)
                    label(frame, opts.Name or "Toggle")

                    local box = new("TextButton", {
                        AnchorPoint = Vector2.new(1, 0.5),
                        AutoButtonColor = false,
                        BackgroundColor3 = Theme.Element,
                        BorderSizePixel = 0,
                        Position = UDim2.new(1, 0, 0.5, 0),
                        Size = UDim2.fromOffset(20, 20),
                        Text = "",
                    }, frame)
                    corner(box, 4)

                    local tick = new("TextLabel", {
                        BackgroundTransparency = 1,
                        Font = Theme.FontBold,
                        Size = UDim2.fromScale(1, 1),
                        Text = "✓",
                        TextColor3 = Theme.Accent,
                        TextSize = 16,
                        TextTransparency = 1,
                    }, box)

                    local Toggle = { Value = false }

                    function Toggle:Set(value)
                        Toggle.Value = value and true or false
                        tween(tick, { TextTransparency = Toggle.Value and 0 or 1 }, 0.12)

                        if opts.Flag then
                            Library.Flags[opts.Flag] = Toggle.Value
                        end

                        if opts.Callback then
                            task.spawn(opts.Callback, Toggle.Value)
                        end
                    end

                    function Toggle:Get()
                        return Toggle.Value
                    end

                    track(box.MouseButton1Click:Connect(function()
                        Toggle:Set(not Toggle.Value)
                    end))
                    track(box.MouseEnter:Connect(function() tween(box, { BackgroundColor3 = Theme.ElementHover }, 0.1) end))
                    track(box.MouseLeave:Connect(function() tween(box, { BackgroundColor3 = Theme.Element }, 0.1) end))

                    if opts.Default then
                        Toggle:Set(true)
                    elseif opts.Flag then
                        Library.Flags[opts.Flag] = false
                    end

                    return Toggle
                end

                -------------------------------------------------- slider: label above, a box with the value in the middle and a short white fill line

                function Section:AddSlider(opts)
                    opts = opts or {}
                    local min, max = opts.Min or 0, opts.Max or 100
                    local decimals = opts.Decimals or 0
                    local inline = opts.Inline == true

                    local frame = row(inline and 22 or 44, opts.Name)
                    label(frame, opts.Name or "Slider", inline and 0.5 or 1)

                    local bar = new("TextButton", {
                        AnchorPoint = Vector2.new(1, 0),
                        AutoButtonColor = false,
                        BackgroundColor3 = Theme.Element,
                        BorderSizePixel = 0,
                        Position = inline and UDim2.new(1, 0, 0, 1) or UDim2.new(1, 0, 0, 22),
                        Size = inline and UDim2.new(0.45, 0, 0, 20) or UDim2.new(0.6, 0, 0, 20),
                        Text = "",
                    }, frame)
                    corner(bar, 4)

                    local fill = new("Frame", {
                        AnchorPoint = Vector2.new(0, 1),
                        BackgroundColor3 = Theme.Text,
                        BorderSizePixel = 0,
                        Position = UDim2.new(0, 6, 1, -4),
                        Size = UDim2.new(0, 0, 0, 1),
                    }, bar)

                    local valueText = new("TextLabel", {
                        BackgroundTransparency = 1,
                        Font = Theme.Font,
                        Size = UDim2.fromScale(1, 1),
                        Text = "",
                        TextColor3 = Theme.Text,
                        TextSize = Theme.TextSize,
                    }, bar)

                    local Slider = { Value = min }

                    function Slider:Set(value)
                        value = math.clamp(round(tonumber(value) or min, decimals), min, max)
                        Slider.Value = value

                        local share = max > min and (value - min) / (max - min) or 0
                        -- the fill line runs along the first half of the box at most, as in the picture
                        fill.Size = UDim2.new(share * 0.5, -6 * share, 0, 1)
                        valueText.Text = formatNumber(value, decimals) .. (opts.Suffix or "")

                        if opts.Flag then
                            Library.Flags[opts.Flag] = value
                        end

                        if opts.Callback then
                            task.spawn(opts.Callback, value)
                        end
                    end

                    function Slider:Get()
                        return Slider.Value
                    end

                    local sliding = false

                    local function fromMouse()
                        local x = UserInputService:GetMouseLocation().X
                        local share = math.clamp((x - bar.AbsolutePosition.X) / math.max(bar.AbsoluteSize.X, 1), 0, 1)
                        Slider:Set(min + (max - min) * share)
                    end

                    track(bar.InputBegan:Connect(function(input)
                        if input.UserInputType == Enum.UserInputType.MouseButton1 then
                            sliding = true
                            fromMouse()
                        end
                    end))

                    track(UserInputService.InputChanged:Connect(function(input)
                        if sliding and input.UserInputType == Enum.UserInputType.MouseMovement then
                            fromMouse()
                        end
                    end))

                    track(UserInputService.InputEnded:Connect(function(input)
                        if input.UserInputType == Enum.UserInputType.MouseButton1 then
                            sliding = false
                        end
                    end))

                    Slider:Set(opts.Default or min)

                    return Slider
                end

                -------------------------------------------------- dropdown: a box with the picked value; the list opens under it

                function Section:AddDropdown(opts)
                    opts = opts or {}
                    local options = opts.Options or {}
                    local multi = opts.Multi == true

                    local frame = row(22, opts.Name)
                    frame.AutomaticSize = Enum.AutomaticSize.Y
                    frame.ClipsDescendants = false
                    label(frame, opts.Name or "Dropdown", 0.45)

                    local box = new("TextButton", {
                        AnchorPoint = Vector2.new(1, 0),
                        AutoButtonColor = false,
                        BackgroundColor3 = Theme.Element,
                        BorderSizePixel = 0,
                        ClipsDescendants = true,
                        Position = UDim2.new(1, 0, 0, 1),
                        Size = UDim2.new(0.55, 0, 0, 20),
                        Font = Theme.Font,
                        Text = "",
                        TextColor3 = Theme.Text,
                        TextSize = Theme.TextSize,
                        TextTruncate = Enum.TextTruncate.AtEnd,
                        TextXAlignment = Enum.TextXAlignment.Left,
                    }, frame)
                    corner(box, 4)
                    new("UIPadding", { PaddingLeft = UDim.new(0, 7), PaddingRight = UDim.new(0, 4) }, box)

                    local list = new("Frame", {
                        AnchorPoint = Vector2.new(1, 0),
                        AutomaticSize = Enum.AutomaticSize.Y,
                        BackgroundColor3 = Theme.Element,
                        BorderSizePixel = 0,
                        Position = UDim2.new(1, 0, 0, 24),
                        Size = UDim2.new(0.55, 0, 0, 0),
                        Visible = false,
                        ZIndex = 5,
                    }, frame)
                    corner(list, 4)
                    new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }, list)
                    new("UIPadding", { PaddingTop = UDim.new(0, 2), PaddingBottom = UDim.new(0, 2) }, list)

                    local Dropdown = { Value = multi and {} or nil }
                    local optionButtons = {}

                    local function shown()
                        if multi then
                            local picked = {}
                            for _, option in ipairs(options) do
                                if Dropdown.Value[option] then
                                    table.insert(picked, option)
                                end
                            end
                            return #picked > 0 and table.concat(picked, ", ") or "None"
                        end

                        return Dropdown.Value or "None"
                    end

                    local function refresh()
                        box.Text = shown()

                        for option, button in pairs(optionButtons) do
                            local on = multi and Dropdown.Value[option] or (not multi and Dropdown.Value == option)
                            button.TextColor3 = on and Theme.Accent or Theme.Text
                        end
                    end

                    function Dropdown:Set(value)
                        if multi then
                            Dropdown.Value = {}

                            for _, option in ipairs(type(value) == "table" and value or { value }) do
                                Dropdown.Value[option] = true
                            end
                        else
                            Dropdown.Value = value
                        end

                        refresh()

                        if opts.Flag then
                            Library.Flags[opts.Flag] = Dropdown.Value
                        end

                        if opts.Callback then
                            task.spawn(opts.Callback, Dropdown.Value)
                        end
                    end

                    function Dropdown:Get()
                        return Dropdown.Value
                    end

                    function Dropdown:SetOptions(newOptions)
                        options = newOptions

                        for _, button in pairs(optionButtons) do
                            button:Destroy()
                        end
                        optionButtons = {}

                        for index, option in ipairs(options) do
                            local button = new("TextButton", {
                                AutoButtonColor = false,
                                BackgroundTransparency = 1,
                                Font = Theme.Font,
                                LayoutOrder = index,
                                Size = UDim2.new(1, 0, 0, 20),
                                Text = "  " .. option,
                                TextColor3 = Theme.Text,
                                TextSize = Theme.TextSize,
                                TextXAlignment = Enum.TextXAlignment.Left,
                                ZIndex = 6,
                            }, list)

                            optionButtons[option] = button

                            track(button.MouseButton1Click:Connect(function()
                                if multi then
                                    Dropdown.Value[option] = not Dropdown.Value[option] or nil
                                    Dropdown:Set((function()
                                        local picked = {}
                                        for _, o in ipairs(options) do
                                            if Dropdown.Value[o] then
                                                table.insert(picked, o)
                                            end
                                        end
                                        return picked
                                    end)())
                                else
                                    Dropdown:Set(option)
                                    list.Visible = false
                                end
                            end))
                        end

                        refresh()
                    end

                    track(box.MouseButton1Click:Connect(function()
                        list.Visible = not list.Visible
                    end))

                    Dropdown:SetOptions(options)
                    Dropdown:Set(opts.Default or (multi and {} or options[1]))

                    return Dropdown
                end

                -------------------------------------------------- button and label

                function Section:AddButton(opts)
                    opts = opts or {}
                    local frame = row(24, opts.Name)

                    local button = new("TextButton", {
                        AutoButtonColor = false,
                        BackgroundColor3 = Theme.Element,
                        BorderSizePixel = 0,
                        Font = Theme.Font,
                        Size = UDim2.fromScale(1, 1),
                        Text = opts.Name or "Button",
                        TextColor3 = Theme.Text,
                        TextSize = Theme.TextSize,
                    }, frame)
                    corner(button, 4)

                    track(button.MouseEnter:Connect(function() tween(button, { BackgroundColor3 = Theme.ElementHover }, 0.1) end))
                    track(button.MouseLeave:Connect(function() tween(button, { BackgroundColor3 = Theme.Element }, 0.1) end))
                    track(button.MouseButton1Click:Connect(function()
                        if opts.Callback then
                            task.spawn(opts.Callback)
                        end
                    end))

                    return button
                end

                function Section:AddLabel(text)
                    local frame = row(20, text)
                    local l = label(frame, text, 1)
                    l.TextColor3 = Theme.TextDim
                    return l
                end

                return Section
            end

            return Api
        end

        -- a tab with no sub tabs uses this page directly
        local mainColumns = makeColumns(body)
        local mainApi = makeSectionApi(mainColumns)

        function Tab:AddSection(sectionName, side)
            return mainApi:AddSection(sectionName, side)
        end

        function Tab:AddSubTab(subName)
            subCount += 1

            -- the first sub tab moves the body down under the pills
            if subCount == 1 then
                pillBar.Visible = true
                body.Position = UDim2.fromOffset(0, 38)
                body.Size = UDim2.new(1, 0, 1, -38)
                mainColumns.Left.Visible = false
                mainColumns.Right.Visible = false
            end

            local pill = new("TextButton", {
                AutoButtonColor = false,
                BackgroundColor3 = Theme.Pill,
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                Font = Theme.Font,
                LayoutOrder = subCount,
                Size = UDim2.fromOffset(70, 26),
                Text = subName,
                TextColor3 = Theme.TextDim,
                TextSize = Theme.TextSize,
            }, pillBar)
            corner(pill, 5)

            local holder = new("Frame", {
                Name = subName,
                BackgroundTransparency = 1,
                Position = UDim2.fromOffset(6, 6),
                Size = UDim2.new(1, -12, 1, -12),
                Visible = false,
            }, body)

            local Sub = { Pill = pill, Holder = holder }
            local api = makeSectionApi(makeColumns(holder))

            function Sub:AddSection(sectionName, side)
                return api:AddSection(sectionName, side)
            end

            local function pick()
                if currentSub then
                    currentSub.Holder.Visible = false
                    tween(currentSub.Pill, { BackgroundTransparency = 1, TextColor3 = Theme.TextDim })
                end

                currentSub = Sub
                holder.Visible = true
                tween(pill, { BackgroundTransparency = 0, TextColor3 = Theme.Text })
            end

            track(pill.MouseButton1Click:Connect(pick))

            if not currentSub then
                pick()
            end

            table.insert(Tab.SubTabs, Sub)
            return Sub
        end

        -- the main columns sit inside the body with the same inner margin as a sub tab
        for _, column in pairs(mainColumns) do
            column.Position = column.Position + UDim2.fromOffset(6, 6)
            column.Size = column.Size + UDim2.fromOffset(-6, -12)
        end

        table.insert(Window.Tabs, Tab)
        return Tab
    end

    function Window:Unload()
        for _, connection in ipairs(Library.Connections) do
            pcall(function()
                connection:Disconnect()
            end)
        end

        table.clear(Library.Connections)
        gui:Destroy()
    end

    return Window
end

