local function playerNames()
    local names = {}

    for _, player in ipairs(Players:GetPlayers()) do
        if player ~= LocalPlayer then
            table.insert(names, player.Name)
        end
    end

    table.sort(names)
    return names
end

playerDropdown = listSection:AddDropdown({
    Name = "Player",
    Options = playerNames(),
    Callback = function(name)
